<template><div class="binding-editor"><div v-for="(binding,index) in rows" :key="index" class="binding-row"><el-select :model-value="binding.output_id" placeholder="函数输出" @update:model-value="updateRow(index,'output_id',$event)"><el-option v-for="item in outputs" :key="item.output_id" :label="item.name" :value="item.output_id" /></el-select><el-input :model-value="binding.value" placeholder="常量 / 表达式 / $local.name" @update:model-value="updateRow(index,'value',$event)" /><el-button text type="danger" title="删除返回值" @click="removeRow(index)"><X :size="14" /></el-button></div><el-button size="small" plain @click="addRow"><Plus :size="14" />添加返回值</el-button></div></template>
<script setup>
import { computed } from 'vue'; import { Plus, X } from 'lucide-vue-next'; import { useProjectStore } from '@/stores'
const props=defineProps({modelValue:{type:Array,default:()=>[]}});const emit=defineEmits(['update:modelValue']);const store=useProjectStore();const rows=computed(()=>Array.isArray(props.modelValue)?props.modelValue:[]);const outputs=computed(()=>store.currentFunction?.outputs||[]);const addRow=()=>emit('update:modelValue',[...rows.value,{output_id:'',value:''}]);const removeRow=index=>emit('update:modelValue',rows.value.filter((_,i)=>i!==index));const updateRow=(index,key,value)=>emit('update:modelValue',rows.value.map((item,i)=>i===index?{...item,[key]:value}:item))
</script>
<style scoped>.binding-editor{display:flex;flex-direction:column;width:100%;gap:6px}.binding-row{display:grid;grid-template-columns:minmax(100px,.8fr) minmax(150px,1.4fr) 28px;gap:6px}</style>
